styles:
* { margin: 0; padding: 0; box-sizing: border-box; }

.about-hero {
    position: relative;
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 80px 40px 60px;
    overflow: hidden;
    background: transparent;
    font-family: 'Space Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.about-hero-content {
    position: relative;
    z-index: 2;
    max-width: 1600px;
    width: 100%;
    margin: 0 auto;
}

.about-hero-content > div {
    max-width: 1100px;
}

.about-hero-subtitle {
    font-size: clamp(0.5rem, 1.2vw, 0.7rem);
    font-weight: 300;
    letter-spacing: clamp(2px, 0.5vw, 4px);
    color: rgba(255, 255, 255, 0.5);
    margin-bottom: 30px;
    text-transform: uppercase;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.about-hero-title {
    font-size: clamp(0.5rem, 8vw, 6rem);
    font-weight: 300;
    line-height: 1;
    margin-bottom: 50px;
    letter-spacing: -0.05em;
    overflow: visible;
    color: #ffffff;
}

.about-hero-title span {
    display: block;
}

.about-title-line-1, .about-title-line-3 {
    color: rgba(255, 255, 255, 0.95);
}

/* DGS Brand Gradient: Cyan → Magenta → Orange */
.about-title-line-2 {
    background: linear-gradient(90deg, #00D4FF 0%, #FF00DC 50%, #FF6B35 100%);
    background-size: 200% 100%;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    will-change: background-position;
    animation: aboutGradientSlide 15s linear infinite;
    padding-bottom: 10px;
    filter: brightness(1.2) saturate(1.15);
}

.about-hero-description {
    font-size: clamp(1rem, 1.8vw, 1.35rem);
    font-weight: 400;
    line-height: 1.6;
    color: rgba(255, 255, 255, 0.7);
    max-width: 850px;
    margin-bottom: 60px;
    letter-spacing: -0.01em;
}

.about-hero-stats {
    display: flex;
    align-items: center;
    gap: 2.5rem;
    flex-wrap: wrap;
    margin-bottom: 50px;
}

.about-stat-item {
    text-align: left;
}

.about-stat-number {
    font-size: clamp(2rem, 3.5vw, 2.75rem);
    font-weight: 500;
    color: #ffffff;
    line-height: 1;
    margin-bottom: 0.5rem;
}

.about-stat-label {
    font-size: clamp(0.85rem, 1.2vw, 0.95rem);
    color: rgba(255, 255, 255, 0.55);
    font-weight: 400;
}

.about-stat-divider {
    width: 1px;
    height: 50px;
    background: rgba(255, 255, 255, 0.15);
}

.about-hero-cta {
    padding-top: 8px;
}

.about-hero-explore-btn {
    font-size: clamp(0.75rem, 1.5vw, 0.85rem);
    font-weight: 500;
    letter-spacing: clamp(2px, 0.5vw, 3px);
    color: #fff;
    text-decoration: none;
    text-transform: uppercase;
    border-bottom: 1px solid rgba(255, 255, 255, 0.3);
    padding-bottom: 8px;
    display: inline-block;
    white-space: nowrap;
    transition: all 0.3s ease;
    cursor: pointer;
}

/* DGS Orange hover */
.about-hero-explore-btn:hover {
    border-bottom-color: #FF6B35;
    padding-left: 12px;
    color: #FF6B35;
}

.about-scroll-indicator {
    position: absolute;
    bottom: 60px;
    left: 40px;
    z-index: 2;
}

.about-scroll-line {
    width: 1px;
    height: 80px;
    background: linear-gradient(180deg, transparent, rgba(255, 255, 255, 0.3), transparent);
    position: relative;
}

/* DGS Brand Gradient for scroll line */
.about-scroll-line-inner {
    width: 1px;
    height: 20px;
    background: linear-gradient(180deg, #00D4FF, #FF00DC, #FF6B35);
    position: absolute;
    top: 0;
    will-change: transform;
    animation: aboutScrollLineDrop 2s ease infinite;
}

@keyframes aboutGradientSlide {
    0% { background-position: 0% 50%; }
    100% { background-position: 200% 50%; }
}

@keyframes aboutScrollLineDrop {
    0% { transform: translateY(0); opacity: 0; }
    50% { opacity: 1; }
    100% { transform: translateY(60px); opacity: 0; }
}

@media (max-width: 968px) {
    .about-hero {
        padding: 120px 20px 60px !important;
    }
    .about-hero-title {
        font-size: clamp(3.5rem, 14vw, 5rem) !important;
        margin-bottom: 40px !important;
        line-height: 0.95 !important;
    }
    .about-hero-subtitle {
        font-size: 0.5rem !important;
        letter-spacing: 1.5px !important;
        margin-bottom: 25px !important;
    }
    .about-hero-description {
        font-size: clamp(0.95rem, 2vw, 1.1rem) !important;
        margin-bottom: 45px !important;
    }
    .about-hero-stats {
        gap: 1.5rem 1.2rem !important;
        margin-bottom: 40px !important;
    }
    .about-stat-divider {
        display: none;
    }
    .about-scroll-indicator {
        left: 20px;
        bottom: 40px;
    }
}

@media (max-width: 480px) {
    .about-hero-title {
        font-size: clamp(3rem, 13vw, 4rem) !important;
    }
    .about-hero-explore-btn {
        font-size: 0.7rem !important;
        letter-spacing: 1.5px !important;
    }
}

.founders-section {
    position: relative;
    padding: 120px 40px;
    background: transparent;
    font-family: 'Space Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    overflow: hidden;
}

.founders-container {
    max-width: 1600px;
    margin: 0 auto;
    position: relative;
    z-index: 2;
}

.founders-section-label {
    font-size: clamp(0.5rem, 1.2vw, 0.7rem);
    font-weight: 300;
    letter-spacing: clamp(2px, 0.5vw, 4px);
    color: rgba(255, 255, 255, 0.5);
    margin-bottom: 30px;
    text-transform: uppercase;
}

.founders-section-title {
    font-size: clamp(2.5rem, 5vw, 4.5rem);
    font-weight: 500;
    line-height: 1.15;
    margin-bottom: 40px;
    letter-spacing: -0.03em;
    color: rgba(255, 255, 255, 0.98);
    max-width: 900px;
}

.founders-intro {
    font-size: clamp(1.1rem, 1.8vw, 1.45rem);
    font-weight: 400;
    line-height: 1.7;
    color: rgba(255, 255, 255, 0.75);
    max-width: 1100px;
    margin-bottom: 80px;
    letter-spacing: -0.01em;
}

.gradient-highlight {
    background: linear-gradient(90deg, #00D4FF 0%, #FF00DC 50%, #FF6B35 100%);
    background-size: 200% 100%;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    animation: textGradientFlow 8s linear infinite;
    font-weight: 600;
}

/* Journey Timeline */
.journey-timeline {
    position: relative;
    max-width: 1200px;
    margin: 0 auto 100px;
    padding-left: 80px;
}

.journey-timeline::before {
    content: '';
    position: absolute;
    left: 20px;
    top: 0;
    width: 3px;
    height: 100%;
    background: linear-gradient(180deg, #00D4FF 0%, #FF00DC 50%, #FF6B35 100%);
    opacity: 0.3;
}

.timeline-item {
    position: relative;
    margin-bottom: 50px;
    padding: 35px 40px;
    background: linear-gradient(135deg, rgba(0, 212, 255, 0.08) 0%, rgba(255, 0, 220, 0.05) 50%, rgba(255, 107, 53, 0.08) 100%);
    backdrop-filter: blur(20px);
    border-left: 3px solid transparent;
    border-radius: 16px;
    transition: all 0.5s ease;
}

.timeline-item::before {
    content: '';
    position: absolute;
    left: -83px;
    top: 40px;
    width: 20px;
    height: 20px;
    background: linear-gradient(135deg, #00D4FF 0%, #FF00DC 50%, #FF6B35 100%);
    border-radius: 50%;
    box-shadow: 0 0 20px rgba(0, 212, 255, 0.5);
    animation: pulse 2s ease infinite;
}

.timeline-item:hover {
    border-left-color: #FF6B35;
    transform: translateX(12px);
    box-shadow: 0 15px 50px rgba(255, 107, 53, 0.2);
}

.timeline-year {
    font-size: clamp(0.75rem, 1vw, 0.85rem);
    font-weight: 600;
    letter-spacing: 3px;
    color: #FF6B35;
    margin-bottom: 12px;
    text-transform: uppercase;
}

.timeline-milestone {
    font-size: clamp(1.25rem, 1.8vw, 1.6rem);
    font-weight: 600;
    color: #ffffff;
    margin-bottom: 12px;
    letter-spacing: -0.02em;
}

.timeline-description {
    font-size: clamp(0.95rem, 1.15vw, 1.05rem);
    line-height: 1.6;
    color: rgba(255, 255, 255, 0.7);
}

/* Founders Grid */
.founders-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(500px, 1fr));
    gap: 3rem;
    margin-top: 80px;
}

.founder-card {
    position: relative;
    background: linear-gradient(135deg, rgba(0, 212, 255, 0.06) 0%, rgba(255, 0, 220, 0.04) 50%, rgba(255, 107, 53, 0.06) 100%);
    backdrop-filter: blur(25px);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 24px;
    overflow: hidden;
    transition: all 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.founder-card::before {
    content: '';
    position: absolute;
    top: -2px;
    left: -2px;
    right: -2px;
    bottom: -2px;
    background: linear-gradient(135deg, #00D4FF 0%, #FF00DC 50%, #FF6B35 100%);
    border-radius: 24px;
    opacity: 0;
    transition: opacity 0.5s ease;
    z-index: -1;
}

.founder-card:hover::before {
    opacity: 0.15;
}

.founder-card:hover {
    transform: translateY(-10px);
    box-shadow: 
        0 30px 80px rgba(0, 212, 255, 0.2),
        0 40px 100px rgba(255, 0, 220, 0.15),
        inset 0 1px 0 rgba(255, 255, 255, 0.2);
}

.founder-image-wrapper {
    position: relative;
    width: 100%;
    height: auto;
    min-height: 700px;
    background: linear-gradient(135deg, rgba(0, 212, 255, 0.2) 0%, rgba(255, 0, 220, 0.15) 50%, rgba(255, 107, 53, 0.2) 100%);
    display: flex;
    align-items: flex-end;
    justify-content: center;
    padding: 20px;
}

.founder-image-placeholder {
    font-size: 1rem;
    color: rgba(255, 255, 255, 0.4);
    text-align: center;
    padding: 20px;
    letter-spacing: 1px;
}

.founder-image {
    width: 100%;
    max-width: 100%;
    height: auto;
    transition: transform 0.6s ease;
}

.founder-card:hover .founder-image {
    transform: scale(1.08);
}

.founder-content {
    padding: 45px 40px 50px;
}

.founder-badge {
    display: inline-block;
    padding: 8px 18px;
    background: linear-gradient(90deg, rgba(0, 212, 255, 0.15) 0%, rgba(255, 0, 220, 0.15) 50%, rgba(255, 107, 53, 0.15) 100%);
    border: 1px solid rgba(255, 107, 53, 0.3);
    border-radius: 100px;
    font-size: 0.75rem;
    font-weight: 600;
    letter-spacing: 2px;
    color: #FF6B35;
    text-transform: uppercase;
    margin-bottom: 20px;
}

.founder-name {
    font-size: clamp(2rem, 2.8vw, 2.5rem);
    font-weight: 700;
    color: #ffffff;
    margin-bottom: 10px;
    letter-spacing: -0.03em;
}

.founder-title {
    font-size: clamp(1.05rem, 1.3vw, 1.2rem);
    font-weight: 500;
    background: linear-gradient(90deg, #00D4FF 0%, #FF00DC 50%, #FF6B35 100%);
    background-size: 200% 100%;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    animation: textGradientFlow 8s linear infinite;
    margin-bottom: 28px;
    letter-spacing: 0.5px;
}

.founder-divider {
    width: 60px;
    height: 3px;
    background: linear-gradient(90deg, #00D4FF 0%, #FF00DC 50%, #FF6B35 100%);
    margin: 25px 0;
    border-radius: 10px;
}

.founder-expertise-label {
    font-size: 0.85rem;
    font-weight: 600;
    letter-spacing: 2px;
    color: rgba(255, 255, 255, 0.5);
    text-transform: uppercase;
    margin-bottom: 15px;
}

.founder-role-description {
    font-size: clamp(1rem, 1.2vw, 1.1rem);
    font-weight: 400;
    line-height: 1.7;
    color: rgba(255, 255, 255, 0.8);
    margin-bottom: 30px;
    letter-spacing: -0.01em;
}

.founder-achievements {
    margin-bottom: 30px;
}

.achievement-label {
    font-size: 0.85rem;
    font-weight: 600;
    letter-spacing: 2px;
    color: rgba(255, 255, 255, 0.5);
    text-transform: uppercase;
    margin-bottom: 15px;
}

.achievement-list {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.achievement-item {
    display: flex;
    align-items: flex-start;
    gap: 14px;
    font-size: clamp(0.95rem, 1.1vw, 1.02rem);
    color: rgba(255, 255, 255, 0.75);
    line-height: 1.6;
}

.achievement-item::before {
    content: '✦';
    color: #FF6B35;
    font-size: 1rem;
    flex-shrink: 0;
    margin-top: 2px;
}

.founder-brands {
    margin-bottom: 32px;
}

.brands-label {
    font-size: 0.85rem;
    font-weight: 600;
    letter-spacing: 2px;
    color: rgba(255, 255, 255, 0.5);
    text-transform: uppercase;
    margin-bottom: 15px;
}

.brands-list {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
}

.brand-tag {
    padding: 8px 16px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 100px;
    font-size: 0.85rem;
    color: rgba(255, 255, 255, 0.8);
    transition: all 0.3s ease;
}

.brand-tag:hover {
    background: rgba(255, 107, 53, 0.15);
    border-color: rgba(255, 107, 53, 0.4);
    color: #ffffff;
}

.founder-stats {
    display: flex;
    gap: 20px;
    flex-wrap: wrap;
    margin-bottom: 28px;
}

.stat-box {
    flex: 1;
    min-width: 140px;
    padding: 20px;
    background: linear-gradient(135deg, rgba(0, 212, 255, 0.1) 0%, rgba(255, 107, 53, 0.1) 100%);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 16px;
    text-align: center;
}

.stat-number {
    font-size: clamp(2rem, 3vw, 2.5rem);
    font-weight: 700;
    background: linear-gradient(90deg, #00D4FF 0%, #FF00DC 50%, #FF6B35 100%);
    background-size: 200% 100%;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    animation: textGradientFlow 8s linear infinite;
    line-height: 1;
    margin-bottom: 8px;
}

.stat-label {
    font-size: 0.85rem;
    color: rgba(255, 255, 255, 0.6);
    font-weight: 500;
}

/* LinkedIn Link */
.founder-linkedin {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 12px 22px;
    background: rgba(10, 102, 194, 0.12);
    border: 1px solid rgba(10, 102, 194, 0.35);
    border-radius: 100px;
    font-size: 0.88rem;
    font-weight: 600;
    color: rgba(255, 255, 255, 0.85);
    letter-spacing: 0.5px;
    text-decoration: none;
    transition: all 0.3s ease;
}

.founder-linkedin:hover {
    background: rgba(10, 102, 194, 0.28);
    border-color: rgba(10, 102, 194, 0.7);
    color: #ffffff;
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(10, 102, 194, 0.25);
}

.founder-linkedin svg {
    width: 18px;
    height: 18px;
    fill: #0A66C2;
    flex-shrink: 0;
    transition: transform 0.3s ease;
}

.founder-linkedin:hover svg {
    transform: scale(1.1);
}

@keyframes textGradientFlow {
    0% { background-position: 0% 50%; }
    100% { background-position: 200% 50%; }
}

@keyframes pulse {
    0%, 100% {
        transform: scale(1);
        box-shadow: 0 0 20px rgba(0, 212, 255, 0.5);
    }
    50% {
        transform: scale(1.15);
        box-shadow: 0 0 30px rgba(255, 0, 220, 0.8);
    }
}

@media (max-width: 1100px) {
    .founders-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 968px) {
    .founders-section {
        padding: 80px 20px !important;
    }

    .founders-intro {
        margin-bottom: 60px !important;
    }

    .journey-timeline {
        padding-left: 60px;
        margin-bottom: 70px !important;
    }

    .journey-timeline::before {
        left: 15px;
    }

    .timeline-item::before {
        left: -63px;
    }

    .founders-grid {
        gap: 2.5rem;
        margin-top: 60px !important;
    }

    .founder-image-wrapper {
        min-height: 600px;
    }

    .founder-content {
        padding: 38px 32px 42px;
    }
}

@media (max-width: 580px) {
    .founders-section {
        padding: 60px 20px !important;
    }

    .journey-timeline {
        padding-left: 40px;
    }

    .timeline-item {
        padding: 25px 20px;
    }

    .timeline-item::before {
        left: -50px;
        width: 16px;
        height: 16px;
    }

    .timeline-item:hover {
        transform: translateX(6px);
    }

    .founder-image-wrapper {
        min-height: 500px;
    }

    .founder-content {
        padding: 32px 26px 36px;
    }

    .founder-stats {
        flex-direction: column;
    }
}

