}

/* Decorative gradient orb */
.strength-card::after {
    content: '';
    position: absolute;
    width: 150px;
    height: 150px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(255, 107, 53, 0.3) 0%, transparent 70%);
    top: -75px;
    right: -75px;
    opacity: 0;
    transition: all 0.6s ease;
    filter: blur(40px);
    z-index: 0;
}

.strength-card:hover::after {
    opacity: 1;
    transform: scale(1.5);
}

@keyframes textGradientSlide {
